/** Response of `POST /api/orders`. Amounts are server-formatted, like `/api/cart/quote`: `19.99 USD`. */
export interface OrderSummary {
  id: string
  subtotal: string
  discount: string
  total: string
}

/** Response of `GET /api/orders/:id`. */
export interface Order extends OrderSummary {
  lines: {
    slug: string
    name: string
    qty: number
  }[]
}

import type { CartLine } from '#shared/types/cart'
import type { Order, OrderSummary } from '#shared/types/order'

interface StoredOrder {
  id: string
  lines: CartLine[]
  subtotal: string
  discount: string
  total: string
}

/** Orders live in server memory only, so they are lost when the server restarts. */
const orders = new Map<string, StoredOrder>()

/** Charges the cart with the same pricing as the quote API and stores the order. */
export function placeOrder(lines: CartLine[], code?: string): OrderSummary {
  const quote = computeQuote(lines, code)
  const order: StoredOrder = {
    id: crypto.randomUUID(),
    lines: lines.map(({ slug, qty }) => ({ slug, qty })),
    ...quote,
  }
  orders.set(order.id, order)
  return { id: order.id, subtotal: order.subtotal, discount: order.discount, total: order.total }
}

export function getOrder(id: string): Order | undefined {
  const order = orders.get(id)
  if (!order)
    return undefined
  return {
    id: order.id,
    subtotal: order.subtotal,
    discount: order.discount,
    total: order.total,
    lines: order.lines.map(line => ({
      slug: line.slug,
      name: findProduct(line.slug)?.name ?? line.slug,
      qty: line.qty,
    })),
  }
}

import type { CartLine } from '#shared/types/cart'

export default defineEventHandler(async (event) => {
  const body = await readBody<{ lines?: unknown, code?: unknown }>(event)
  const lines = body?.lines
  if (!Array.isArray(lines) || lines.length === 0)
    throw createError({ statusCode: 400, statusMessage: 'Order needs at least one line' })
  for (const line of lines) {
    const { slug, qty } = (line ?? {}) as Partial<CartLine>
    if (typeof slug !== 'string' || !findProduct(slug))
      throw createError({ statusCode: 400, statusMessage: `Unknown product: ${String(slug)}` })
    if (!Number.isInteger(qty) || (qty as number) < 1)
      throw createError({ statusCode: 400, statusMessage: 'Quantity must be a positive integer' })
  }
  if (body.code != null && typeof body.code !== 'string')
    throw createError({ statusCode: 400, statusMessage: 'Discount code must be a string' })
  return placeOrder(lines as CartLine[], body.code ?? undefined)
})

export default defineEventHandler((event) => {
  const order = getOrder(getRouterParam(event, 'id') ?? '')
  if (!order)
    throw createError({ statusCode: 404, statusMessage: 'Order not found' })
  return order
})
